import 'dart:convert';
import 'dart:io';

class _Patch {
  const _Patch({
    required this.path,
    required this.label,
    required this.oldBase64,
    required this.newBase64,
  });

  final String path;
  final String label;
  final String oldBase64;
  final String newBase64;

  String get oldText => utf8.decode(base64.decode(oldBase64));
  String get newText => utf8.decode(base64.decode(newBase64));
}

String _normalize(String value) =>
    value.replaceAll('\r\n', '\n').replaceAll('\r', '\n');

int _occurrences(String haystack, String needle) {
  if (needle.isEmpty) return 0;
  var count = 0;
  var offset = 0;
  while (true) {
    final index = haystack.indexOf(needle, offset);
    if (index < 0) return count;
    count += 1;
    offset = index + needle.length;
  }
}

void main() {
  final root = Directory.current;
  final files = <String, String>{};

  for (final path in _patches.map((patch) => patch.path).toSet()) {
    final file = File('${root.path}${Platform.pathSeparator}'
        '${path.replaceAll('/', Platform.pathSeparator)}');
    if (!file.existsSync()) {
      stderr.writeln('Missing required file: $path');
      exitCode = 2;
      return;
    }
    files[path] = _normalize(file.readAsStringSync(encoding: utf8));
  }

  final applied = <String>[];
  final alreadyApplied = <String>[];

  // Validate and stage every patch in memory. Nothing is written until all
  // 30 contracts have been checked successfully.
  for (final patch in _patches) {
    var text = files[patch.path]!;
    final oldText = _normalize(patch.oldText).trimRight();
    final newText = _normalize(patch.newText).trimRight();

    if (text.contains(newText)) {
      alreadyApplied.add(patch.label);
      stdout.writeln('Already applied: ${patch.label}');
      continue;
    }

    final count = _occurrences(text, oldText);
    if (count != 1) {
      stderr.writeln(
        "Cannot apply '${patch.label}': expected old block exactly once, "
        'found $count. No production files were written.',
      );
      exitCode = 3;
      return;
    }

    text = text.replaceFirst(oldText, newText);
    files[patch.path] = text;
    applied.add(patch.label);
    stdout.writeln('Prepared: ${patch.label}');
  }

  for (final entry in files.entries) {
    final file = File('${root.path}${Platform.pathSeparator}'
        '${entry.key.replaceAll('/', Platform.pathSeparator)}');
    file.writeAsStringSync(entry.value, encoding: utf8, flush: true);
  }

  stdout.writeln('');
  stdout.writeln('Phase 7+8 UTF-8 production patch applied successfully.');
  stdout.writeln('Prepared changes: ${applied.length}');
  stdout.writeln('Already present: ${alreadyApplied.length}');
  stdout.writeln('Production files written: ${files.length}');
  stdout.writeln('');
  stdout.writeln('Next: dart format lib test');
  stdout.writeln('Then: flutter analyze');
}

